// Один длинный опрос за раз. Schedule Trigger стреляет каждые 5 с, а HTTP
// висит до 25 с, поэтому без замка запуски накладывались бы друг на друга и
// два параллельных запроса могли получить одни и те же события.
const store = $getWorkflowStaticData('global');
const now = Date.now();
const lockUntil = typeof store.pollUntil === 'number' ? store.pollUntil : 0;
if (lockUntil > now) {
  return [{ json: { skip: true, waitMs: lockUntil - now } }];
}
// wait=25 в HTTP-ноде + запас на сеть и БД.
store.pollUntil = now + 26000;
return [{ json: { skip: false, waitMs: 0 } }];

// Ответ GET /integrations/n8n/events: { events: [...], nextCursor: "<id>"|null }
const store = $getWorkflowStaticData('global');
const page = $input.first().json || {};
const events = Array.isArray(page.events) ? page.events : [];

// Курсор двигаем всегда, даже если все события отфильтрованы: иначе они
// придут снова и снова.
if (page.nextCursor) store.cursor = page.nextCursor;
store.lastPollAt = new Date().toISOString();

const picked = events
  // Отвечаем только на новые входящие. Правки/удаления/прочтения и свои
  // собственные сообщения (outgoing) — не повод для ответа.
  .filter((event) => event && event.kind === 'message.new')
  .filter((event) => (event.payload || {}).outgoing !== true)
  .map((event) => {
    const payload = event.payload || {};
    const text = String(payload.text || '').trim();
    const transcript = String(payload.transcript || '').trim();
    return {
      eventId: event.id,
      accountId: event.accountId,
      chatId: event.chatId,
      threadId: event.threadId || 0,
      messageId: payload.messageId ?? null,
      senderName: payload.senderName || '',
      mediaType: payload.mediaType || null,
      text,
      // Промпт для soul-reply: текст, расшифровка голосового или заглушка.
      prompt: text || transcript || '[вложение]',
      createdAt: event.createdAt,
    };
  });

return [{ json: { count: picked.length, events: picked } }];
